quests[33966] = { id = 33966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgrond Flowerpicker" }
quests[33967] = { id = 33967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegengift", description = "Ich mache mir Sorgen um Nyami. Sie ist so darauf konzentriert, das Herz von Auchindoun zurückzubekommen, dass sie alles andere um sich herum zu vergessen scheint.\n\nTut mir leid... Ich will gar nicht ihre Weisheit in Frage stellen, aber schaut Euch doch mal um! Jeder Soldat, den wir in die Mine geschickt haben, wurde durch die Todesnetzspinnen schwer verwundet. Ihre Wunden müssen sofort versorgt werden!\n\nKönntet Ihr vielleicht ein paar Fangzähne der Spinnen erbeuten? Ich kann aus ihnen ein Gegengift entwickeln. Ich selbst muss hier bleiben und mich weiter um die Opfer kümmern.", sourceObjective = "Sammelt 9 Todesnetzzähne in der Todesnetzhöhle ein.", progress = "Habt Ihr die Fangzähne dabei? Uns bleibt nicht viel Zeit!", completion = "Seid gesegnet, {name}. Heute sind schon genug Unschuldige gestorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[33969] = { id = 33969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schändliche Entweiher", description = "Viele Leute fürchten die Spinnen in der überrannten Mine in der Nähe. Ihr Gift soll die Gestalt ihrer Opfer selbst verändern. Aus diesem Grund halten sich viele Leute fern von dort, aber ich fürchte, dass der Schattenrat irgendwie an diese Informationen gelangt ist.\n\nUnsere Späher berichten, dass ihre Hexenmeister diese Spinnen zusätzlich mit teuflischer Energie versehen, damit ihr Gift die Opfer in dämonische Schergen verwandelt!\n\nWir müssen die Entweihungskristalle zerstören, damit sich dieser Wahnsinn nicht weiter ausbreiten kann.", sourceObjective = "Zerstört 5 Entweihungskristalle in der Todesnetzhöhle.", completion = "Es war weise von uns, die Gefahren eines gegen uns gerichteten Landes nicht zu unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33970] = { id = 33970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Höhle", description = "Ich habe erfahren, dass der Schattenrat das Gift der Todesnetzspinnen in der Nähe benutzt, um teuflische Verderbnis zu verbreiten und ihre Streitkräfte nach ihrer Niederlage an der Brennenden Front zu verstärken.\n\nEiner meiner Seelenbinder hat einen Schreckenslord dabei beobachtet, wie er sich mit Sha'tari, einem der verbleibenden Teile des Herzens von Auchindoun, in die Minen im Osten aufmachte.\n\nIhr müsst Sha'tari dem bebenden Leichnam des Schreckenslords entreißen und es mir bringen, Champion.", sourceObjective = "Tötet Xanatos den Entweiher in der Todesnetzhöhle und bergt Sha'tari.", progress = "Hatte der teuflische Dämon wie vermutet Sha'tari dabei?", completion = "Genau wie erwartet. Ich danke Euch, {name}. Jetzt wo Sha'tari wieder in unserem Besitz ist, müssen wir nur noch den letzten Teil des Herzens holen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33971] = { id = 33971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegengift", description = "Ich mache mir Sorgen um Nyami. Sie ist so darauf konzentriert, das Herz von Auchindoun zurückzubekommen, dass sie alles andere um sich herum zu vergessen scheint.\n\nTut mir leid... Ich will gar nicht ihre Weisheit in Frage stellen, aber schaut Euch doch mal um! Jeder Soldat, den wir in die Mine geschickt haben, wurde durch die Todesnetzspinnen schwer verwundet. Ihre Wunden müssen sofort versorgt werden!\n\nKönntet Ihr vielleicht ein paar Fangzähne der Spinnen erbeuten? Ich kann aus ihnen ein Gegengift entwickeln. Ich selbst muss hier bleiben und mich weiter um die Opfer kümmern.", sourceObjective = "Sammelt 9 Todesnetzzähne in der Todesnetzhöhle ein.", progress = "Habt Ihr die Fangzähne dabei? Uns bleibt nicht viel Zeit!", completion = "Seid gesegnet, {name}. Heute sind schon genug Unschuldige gestorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[33972] = { id = 33972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schändliche Entweiher", description = "Die Todesnetzspinnen sind bemerkenswerte Kreaturen. Ihr Gift kann die Form ihrer Opfer selbst verändern.\n\nAber wir sind nicht die Einzigen, die über diese Information verfügen. Der Schattenrat hat schon seine Hexenmeister zur Todesnetzhöhle entsandt, um diese Spinnen zusätzlich mit teuflischer Energie zu versehen, damit die Opfer ihres Gifts in dämonische Schergen verwandelt werden!\n\nWir müssen die Entweihungskristalle zerstören und verhindern, dass ganz Talador dem Willen von Teron'gor unterworfen wird!", sourceObjective = "Zerstört 5 Entweihungskristalle in der Todesnetzhöhle.", completion = "<Mehlar lächelt.>\n\nDas Blatt scheint sich zu unseren Gunsten zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33973] = { id = 33973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzter Wunsch", description = "Ihr könnt mich nicht mehr retten, doch habt Dank, dass Ihr mit mir sprecht.\n\nKlingenmeister Bralok und seine Männer ließen mich hungern und schlugen mich. Er stahl ein Erbstück, dass sich bereits im Besitz meiner Familie befand, noch bevor wir auf Draenor ankamen.\n\nSolltet Ihr es finden, lasst es mich bitte noch einmal sehen, damit ich in Frieden sterben kann.", sourceObjective = "Holt Ahms Erbstück von Klingenmeister Bralok zurück.", progress = "Der Klingenmeister muss bezahlen...", completion = "Danke. Jetzt, da ich weiß, dass es sich nicht mehr in den Händen der Eisernen Horde befindet, kann ich in Frieden sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[33974] = { id = 33974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzter Wunsch", description = "Es scheint sich um ein altes draenisches Familienerbstück zu handeln. Den Blutflecken nach zu urteilen wurde es seinem Besitzer gewaltsam abgenommen.\n\nDie Inschrift \"Ahm\" ziert die Rückseite – wahrscheinlich der Name des rechtmäßigen Besitzers.", sourceObjective = "Sprecht mit Ahm beim Belagerungsposten Archenon.", sourceObjectiveStatus = "unverified-source-field" }
quests[33975] = { id = 33975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Blasting Charges - Rubble A" }
quests[33976] = { id = 33976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Stück", description = "Ich bin zu schwer verletzt, um zu kämpfen, {class}. Ich habe meine Stadt und ihre Bewohner enttäuscht. Es liegt jetzt an Euch, diesen Kampf zu entscheiden.\n\nVorpil hält sich gleich da vorne auf. Er versucht, die Kräfte von Auch'naaru für irgendein dunkles Ritual zu missbrauchen.\n\nIhr müsst vollenden, was mir nicht gelungen ist. Streckt Vorpil nieder und sichert Auch'naaru, damit das Herz von Auchindoun wieder vereint wird!", sourceObjective = "Erbeutet Auch'naaru von Vorpil Rippenspalter in Telmor.", progress = "Wir brauchen den letzten Teil des Herzens!", completion = "Gut gemacht! Ich werde Auch'naaru nach Auchindoun bringen. Der Schattenrat hat nichts in unserem Land zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33977] = { id = 33977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Wolfs" }
