quests[33987] = { id = 33987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intro: Suche" }
quests[33988] = { id = 33988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion der Seelenfresser", description = "<Diese Notiz ist eilig auf das Pergament gekritzelt worden.>\n\nTelmor ist verloren. Der Schattenrat häuft unsere Gefallenen zu Leichenbergen an und verfüttert ihre Seelen an ihren Anführer. An meinen Händen klebt Blut...\n\nWer immer diese Nachricht liest... Ich bitte Euch, verbrennt die Leichen unserer Gefallenen, damit der Feind sie nicht missbrauchen kann.\n\n- Restalaan, Hauptmann der Wache", sourceObjective = "Verwendet die Fackeln einer Schmiede, um 4 Leichenberge in Telmor zu entzünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33989] = { id = 33989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Blasting Charges - Cave A Cache" }
