quests[34012] = { id = 34012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche mehr Zähne", description = "<Pirscher Sasha streckt schweigend seine Hand aus und zeigt Euch eine Halskette, die aus fleckigem Leder und fauligen Ogerzähnen gefertigt wurde, alle in einem passenden Farbton des Zerfalls.>\n\n<Sie hat einige Knoten, in denen scheinbar weitere Zähne fehlen.>", sourceObjective = "Sammelt 30 widerliche braune Ogerzähne.", progress = "<Pirscher Sasha starrt Euch mit kalten, mitleidlosen Augen an.>", completion = "<Pirscher Sasha nickt und setzt zwei Halsketten zusammen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[34013] = { id = 34013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Vergessen", description = "Wir mussten aus Telmor fliehen und konnten nur wenige Dinge mitnehmen.\n\nJemand hat Blattschattens Tarnfeld deaktiviert. Ich weiß nicht, wer, aber ich vermute, es war einer von uns.\n\nWir werden unsere Habseligkeiten mit der Zeit wiedererlangen, aber wir können es nicht riskieren, unsere heiligen Artefakte zu verlieren.\n\nWenn Ihr könnt, so bringt Blattschatten, unser Einwohnerverzeichnis und unser Gebetsbuch in Sicherheit.", sourceObjective = "Bergt das Einwohnerverzeichnis von Telmor, das Gebetsbuch der Auchenai und Blattschatten in Telmor.", progress = "Es gibt ein paar Dinge, für die es sich lohnt zu kämpfen, {race}. Und diese gehören dazu.", completion = "Mit Hilfe dieser Gegenstände können wir unsere Gefallenen zählen und alles neu aufbauen. Wir werden überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[34019] = { id = 34019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten erwachen", description = "Wir haben es geschafft, Ner'zhul im Observatorium festzusetzen, aber er hat viele von uns gefangen genommen.\n\nEr hat auch Yrels Schwester, Samaara, in seiner Gewalt.\n\nIch werde hier gebraucht, um die Stellung zu halten. Bitte tut, was in Eurer Macht liegt, um sie zu retten.", sourceObjective = "Stellt Ner'zhul.", completion = "Eure Hilfe bei der Zurückeroberung des Teluuna-Observatoriums ist hier nicht unbemerkt geblieben. Eure Tapferkeit im Kampf beeindruckt mich immer mehr.\n\nVielleicht könntet Ihr Euer Wissen an meine Schüler weitergeben. Sie könnten von einem erfahrenen Abenteurer wie Euch viel lernen.\n\nIch habe etwas für Euch, als Dank für das, was Ihr bereits in der kurzen Zeit bei uns getan habt. Vielleicht hilft es Euch dabei, Eure Garnison zum Laufen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34024] = { id = 34024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungusherz", description = "Die zweite Zutat, die ich für das Elixier benötige, ist schwieriger zu bekommen.\n\nAm Fluss treiben sich Sumpfriesen herum – pilzartige und unersättliche Ungetüme. Ich brauche drei ihrer Herzen.\n\nJe stärker das Herz, desto kräftiger wird die Mixtur und desto klarer meine Sicht.", sourceObjective = "Sammelt 3 Fungusherzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34025] = { id = 34025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nuke Bastion Rise Tracking Flag" }
quests[34026] = { id = 34026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Seismische Angelegenheiten", description = "Einer unserer Nachwuchsfeldmesser liegt mir seit einiger Zeit wegen ungewöhnlicher seismischer Aktivitäten in den Ohren. Ich finde es doch etwas weit hergeholt, dass wir hier versehentlich auf einer Erdspalte gebaut haben sollen. Wir haben alles drei Mal geprüft!\n\nKönntet Ihr vielleicht ein Wörtchen mit ihm reden?", sourceObjective = "Sprecht mit Juniorinspektor Dorn in Eurer Garnison.", completion = "Ach! Kommandant {name}, Ihr kommt gerade richtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[34027] = { id = 34027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bahnbrechende Daten", description = "Aye, wir haben hier alles dreifach überprüft, bevor wir uns hier niederließen. Kein Mucks aus den Tiefen der Erde.\n\nAber heute hat es gerumpelt und es kommt näher! Ich sag Euch, irgendetwas stimmt nicht!\n\nIhr müsst mir nicht einfach so glauben – der Erschütterungssensor hat seine Datensammlung gerade beendet. Seht es Euch selbst an!", sourceObjective = "Benutzt den Erschütterungssensor in Eurer Garnison.", progress = "Nur zu! Probiert den Erschütterungssensor aus. Er wird Euch schon nicht beißen.", completion = "Ich WUSSTE, dass etwas nicht stimmt! HAB ICH'S DOCH GESAGT, Alexston!\n\nAh, Entschuldigung.\n\nHm, wo habe ich derartige Maschinen schon mal gesehen?\n\nOh, ja! Bei den Dunkeleisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34028] = { id = 34028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kommen mir bekannt vor...", description = "Also was macht die Eiserne Horde mit Technologie der Dunkeleisen? Ich weiß, wen wir fragen können!\n\nThaelin Schwarzamboss ist ein genialer Ingenieur vom Dunkeleisenklan, der uns hier auf Draenor schon viel geholfen hat. Vielleicht habt Ihr ihn sogar schon auf Euren Reisen kennengelernt, hm?\n\nMan sagt, er hat irgendwo in Gorgrond einen Bunker gebaut, sozusagen eine geheime Werkstatt. Ihr solltet ihn finden, er weiß möglicherweise etwas hierüber.\n\nÄhm, und seid vorsichtig, ja? Die Dunkeleisenzwerge sind zwar jetzt unsere Verbündeten, aber ich traue ihnen nicht über den Weg.", sourceObjective = "Findet Thaelins Werkstatt in Gorgrond.", completion = "Mmf! Mm- mff!!\n\n<Ihr nehmt ihm den Knebel ab.>\n\nSIE HABEN THAELIN!!", sourceObjectiveStatus = "unverified-source-field" }
quests[34029] = { id = 34029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Prototyp", description = "Vor einigen Tagen tauchte eine Gruppe Orcs der Eisernen Horde hier auf und entführte Thaelin. Sie haben mich als Geisel am Leben gelassen, damit er kooperiert.\n\nIch weiß nicht, wo sie ihn hingebracht haben, aber ich weiß, wie wir ihn finden.\n\nThaelin hat immer einen Peilsender bei sich – und fragt nicht, wo er ihn versteckt. Alles, was er herstellt und das sich bewegen kann, hat einen \"Komm zu Papa\"-Knopf, damit es direkt zu ihm gelangen kann.\n\nIm Nachhinein war das keine besonders sinnvolle Funktion für die wandelnden Bomben... aber perfekt für die Maulwurfmaschine! Springt rein und los geht's!", sourceObjective = "Benutzt den Prototyp der Maulwurfmaschine, um nach Thaelin Schwarzamboss zu suchen.", completion = "Gut genug!", sourceObjectiveStatus = "unverified-source-field" }
quests[34030] = { id = 34030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Ingenieur", sourceObjective = "Findet Thaelin Schwarzamboss im Eisernen Belagerungswerk.", completion = "{name}! Wie gut, Euch zu sehen!\n\nDer Prototyp der Maulwurfmaschine konnte mir vom Laden aus bis hierher folgen? Manchmal beeindrucke ich mich selbst.\n\nJetzt, da Hansel in Sicherheit ist, kann ich den brillanten Fluchtplan durchführen, den ich ausgearbeitet habe. Ich bin froh, dass ich Euch dafür an meiner Seite habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[34031] = { id = 34031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Andenken an mich", description = "Die Eiserne Horde will so unbedingt meine Erfindungen? Dann werden wir ihnen welche zurücklassen.\n\nDiese kleinen hübschen Dinger blasen die Ketten von einem Panzer UND schmelzen das Chassis dabei ein. Schauen wir mal, wie sie ihre schäbigen Kanonen dann hier herausbekommen!", sourceObjective = "Platziert 4 Dunkeleisenminen im Eisernen Belagerungswerk.", completion = "Fürs Protokoll, die Minen haben keine Sprachsteuerung.\n\nDie Lektion habe ich vor einiger Zeit gelernt...", sourceObjectiveStatus = "unverified-source-field" }
quests[34032] = { id = 34032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauliche Informationen", description = "Ich bin nicht die einzige Beute, die die Eiserne Horde nach dem Überfall auf meine Werkstatt gemacht hat.\n\nOberanführer Schwarzhammer, der Irre, der diese Operation leitet, hat mein Notizbuch als seinen persönlichen Schatz mitgenommen.\n\nHerstellungstechniken, Zeichnungen für neue Erfindungen, peinliches Gekritzel.\n\nEs enthält all meine Geheimnisse!\n\nKann ich auf Eure Hilfe zählen, es wiederzubekommen?", sourceObjective = "Plündert Thaelins Notizbuch von Oberanführer Schwarzhammer im Eisernen Belagerungswerk.", progress = "In dem Buch stehen meine Arbeitsnotizen der letzten fünf Jahre. Es ist viel zu gefährlich, es zurückzulassen!", completion = "Aye, da ist es.\n\nDanke, {name}. Sehen wir zu, dass wir hier rauskommen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[34033] = { id = 34033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einen Maulwurf entfernt", description = "Ich glaube, wir haben Hansel lange genug warten lassen. Könnt Ihr mich zu ihm bringen? Dann können wir alle mit der Maulwurfmaschine hier herausfahren.", sourceObjective = "Bringt Thaelin Schwarzamboss zu Hansel Bleihand im Eisernen Belagerungswerk.", completion = "Also kann man wohl annehmen, dass die Sicherheit in meiner alten Werkstatt nicht mehr gewährleistet ist. Wir müssen einen neuen Ort finden, um einen Laden aufzumachen...", sourceObjectiveStatus = "unverified-source-field" }
quests[34034] = { id = 34034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Sand im Getriebe", description = "Kommandant! Die Frostwolforcs am Donnerpass berichten von 'nem furchtbaren knirschenden Geräusch, das durch die Schlucht dröhnt. Wir vermuten, dass es sich um 'ne Kriegsmaschine von der Eisernen Horde handelt.\n\nGazlowe hat sich bereit erklärt, sich das mal anzusehen, aber der will 'ne Gefahrenzulage. Goblins! Trefft Euch mit ihm am Donnerpass und bringt ihm dieses Geld.", sourceObjective = "Bringt Gazlowes Lohn zu Gazlowe am Donnerpass.", progress = "Jo! Habt Ihr die Knete?", completion = "<Gazlowes Gesicht heitert sich auf, als ihr ihm den prall gefüllten Münzbeutel übergebt.>\n\nHeeeeh! Schon viel besser!\n\nIch mache mir nicht gern die Hände schmutzig, aber für so viel Geld könntet Ihr mich sogar dazu bringen, das Plumpsklo der Kor'kron auseinanderzunehmen.\n\nIch bin froh, dass ich ein paar Muskeln zur Verstärkung hier habe – und da ich so ein netter Kerl bin, bekommt Ihr auch etwas für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34035] = { id = 34035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebohrt", description = "Und ob das eine Maschine ist. Ein Bohrer – ein RIESENding! Glücklicherweise müssen wir das nicht auseinandernehmen.\n\nSie verwenden Turbolader und zwei Kompressoren, um Extraschub in die Maschine zu blasen. Ohne den Schub ist der Bohrer nutzlos.\n\nGeht da rein und betätigt die Kupplung am hinteren Ende des Bohrers. Das wird die Aufmerksamkeit ein wenig von den Turbinen ablenken.\n\nIch kümmere mich um die Turbinen – Ihr müsst Euch nur mit den Horden blutrünstiger Orcs befassen.", sourceObjective = "Helft Gazlowe dabei, den Eisernen Steinzermalmer zu sabotieren.", progress = "Kann's losgehen?", completion = "Wisst Ihr... das Ding ist eigentlich ziemlich beeindruckend.\n\nDas Antriebssystem... kommt mir bekannt vor...", sourceObjectiveStatus = "unverified-source-field" }
quests[34039] = { id = 34039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Oberanführer Schwarzhammer", description = "Also, wir KÖNNTEN jetzt gehen. Wir haben das, weshalb wir hergekommen sind und ich habe mich sogar noch als Wohltäter erwiesen, indem ich Thaelin bei der Flucht geholfen habe.\n\nDa wäre aber noch Folgendes.\n\n<Gazlowe hält ein Stück Papier mit einer Zeichnung eines besonders gemein aussehenden Orcs hoch.>\n\nEs gibt ein SI:7-Kopfgeld für einen Oberanführer Schwarzhammer, der zufällig von dieser Anlage aus arbeitet. Wenn Ihr mir helft, ihn zu töten, bezahle ich Euch. Dann bringe ich seinen Kopf zur Allianz und kassiere das Kopfgeld. Alle gewinnen!\n\nNa ja, alle bis auf Schwarzhammer.", sourceObjective = "Tötet Oberanführer Schwarzhammer im Eisernen Belagerungswerk.", completion = "<Gazlowe durchwühlt seinen Beutel und zieht ein einzelnes Goldstück hervor.>\n\nÄh... sieht so aus, als ob ich ein bisschen knapp bei Kasse bin. Gebühren für Leibwächter läppern sich wirklich zusammen!\n\nIch gebe Euch einen angemessenen Anteil, wenn wir zurück in Eurer Garnison sind. Kommt schon, Ihr wisst, dass ich Euch nicht übers Ohr haue!", sourceObjectiveStatus = "unverified-source-field" }
quests[34040] = { id = 34040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kennzeichnung des Herstellers", description = "Ich kapier's nicht – ein Großteil des Schrotts der Eisernen Horde ist in etwa so fortschrittlich, wie ein Gronn mit umgeschnallter Kanone. Sogar der Bohrer ist nichts Besonderes. Doch das Turbosystem ist hochmodern...\n\nDas passt alles überhaupt nicht zusammen!\n\nObwohl ich es eigentlich besser wissen sollte, muss ich herausfinden, wer das hergestellt hat. Ich will mir noch mehr von dem ansehen, was sie im Eisernen Belagerungswerk haben und nach einer Signatur suchen.\n\n<Gazlowe tätschelt den Münzbeutel an seinem Gürtel.>\n\nWas sagt Ihr? Wollt Ihr mein Leibwächter sein?", sourceObjective = "Untersucht 5 Belagerungsteile im Eisernen Belagerungswerk.", completion = "Das ist die Signatur von Schwarzamboss! Ich wusste, ich habe diese Arbeit schon mal irgendwo gesehen.\n\nThaelin Schwarzamboss ist ein Dunkeleisenzwerg, der mit den Streitkräften der Allianz nach Draenor kam und ein verdammt guter Ingenieur ist. Wir stehen in freundschaftlicher Konkurrenz, wenn Ihr so wollt.\n\nAber warum stellt Thaelin Waffen für die Eiserne Horde her?", sourceObjectiveStatus = "unverified-source-field" }
quests[34041] = { id = 34041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vier-Finger-Rabatt", description = "Ich muss zugeben, dass es selbst für mich schwierig ist, eine Versorgungskette zu einer urzeitlichen Welt auf der falschen Seite der Zeit herzustellen. Man muss sich mit, ähm... \"vor Ort erhältlichen\" Waren begnügen.\n\nIhr könnt über die Eiserne Horde sagen, was Ihr wollt, aber was Rohstoffe angeht, haben sie gute Verbindungen!\n\nHaltet im Eisernen Belagerungswerk Ausschau nach wertvollen Gütern. Ich habe einige Raketenhühnchen eingepackt, die wir verwenden können, um die guten Sachen an Eure Garnison zu schicken.", sourceObjective = "Stehlt ein Schwarzfelszahnrad, kondensiertes Geysirgas und einen Kohlenstoffflammenkern aus dem Eisernen Belagerungswerk.", progress = "Der Finderlohn ist nicht verhandelbar!", completion = "Keine schlechte Ausbeute. Hier ist Euer Anteil!", sourceObjectiveStatus = "unverified-source-field" }
quests[34042] = { id = 34042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bastlerkollege", sourceObjective = "Findet Thaelin Schwarzamboss im Eisernen Belagerungswerk.", completion = "Keine Sorge, Thaelin kommt schon klar. Das war meine gute Tat für dieses Jahr – und erzählt es niemandem!\n\nHey... glaubt Ihr, Ihr könntet den Treibstoff als Geschäftsausgaben verbuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[34043] = { id = 34043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In dunkler Nacht", description = "Dieser Schlüsselstein gewährt seinem Träger den Zutritt zur Festung der Pein.\n\nNehmt ihn an Euch und bringt ihn zu Prophet Velen vor der Hauptfestung des Schattenmondklans.\n\nEr hat vor, Ner'zhul offen gegenüberzutreten.", sourceObjective = "Sprecht mit Prophet Velen in der Festung der Pein.\n\nBereitgestellter Gegenstand:", completion = "Gut, Ihr seid eingetroffen. Rulkans Botschaft sagte, Ihr würdet nicht lange brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34047] = { id = 34047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuurem Explosion Tracker" }
quests[34048] = { id = 34048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maulwurfmaschine, geh nach Hause", description = "Mein patentierter \"Komm zu Papa\"-Sprachbefehl war nur der erste Schritt.\n\nIch habe meinen Maulwurfmaschinen auch ein \"Ab nach Hause\"-Kommando einprogrammiert. Damit graben sie sich automatisch zu einer festgelegten Stelle durch – meiner Werkstatt in Gorgrond!\n\nLasst uns die Maulwurfmaschinen nach Hause schicken, bevor die Orcs sie mit ihrem faulen Atem und ihren verschwitzten... Lenden...schurzen vollstinken.\n\n<Ihr hört Thaelin in dem Anzug würgen.>\n\nIgitt!", sourceObjective = "Schickt 5 Maulwurfmaschinen aus dem Eisernen Belagerungswerk nach Hause.", completion = "So, nun sind meine Hübschen vor den Händen der Eisernen Horde in Sicherheit. Jetzt sprießen keine Orcs mehr aus dem Boden!\n\nIch muss nur noch eins erledigen, bevor ich guten Gewissens verschwinden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[34053] = { id = 34053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SoL Conversation Tracker" }
quests[34054] = { id = 34054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Mondes", description = "<Prophet Velens Stimme fährt fort.>\n\nYrel und ich haben Kriegsherr Ner'zhul aufgespürt. Er trifft sich mit Grommash Höllschrei am höchsten Altar, der die Festung der Pein überblickt.\n\nTrefft Euch dort mit uns. Wir müssen ihn aufhalten.", sourceObjective = "Sucht Ner'zhul.", completion = "Wir haben so viele gerettet, wie wir konnten, {name}. Für einige kamen wir einfach zu spät... auch für meine Schwester.\n\nProphet Velen hat recht. Wenn es von uns verlangt wird, müssen wir ALLE kämpfen. Ich gelobe eins: Ich werde meine Lieben nie wieder leiden lassen.\n\nNer'zhul ist kurz davor, den dunklen Stern herabzurufen. Wir sind die Einzigen, die wissen, wie man ihn aufhalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[34060] = { id = 34060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang RRP - Daily Vignette - Rogue Boss" }
quests[34061] = { id = 34061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang RRP - Daily Vignette - Priest Boss" }
quests[34062] = { id = 34062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang RRP - Daily Vignette - Warrior Boss" }
quests[34063] = { id = 34063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde von oben", description = "Mit dem Tod des Eisenwolfs haben wir den Donnerfürsten einen vernichtenden Schlag versetzt, {name}. Trotzdem dürfen wir uns jetzt noch nicht ausruhen.\n\nDie Generäle der Donnerfürsten werden kämpfen wie in die Ecke gedrängte Wölfe, um ihre Stellung innerhalb der Eisernen Horde zu behalten. Für uns sind das schlechte Nachrichten.\n\nIch habe Späher Ruk'gan losgeschickt, um ihre Bewegungen im Auge zu behalten, doch hat er sich seit einiger Zeit nicht mehr gemeldet. Wenn Ihr uns helfen wollt, sucht nach Ruk'gan.\n\nLok'tar, {name}!", sourceObjective = "Sprecht mit Späher Ruk'gan in der Nähe der Knochen von Agurak.", sourceObjectiveStatus = "unverified-source-field" }
quests[34066] = { id = 34066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Rache", description = "Die Donnerfürsten sind eine Plage, {name}.\n\n<Ruk'gan spuckt verächtlich aus.>\n\nMeine Tochter Grishna wurde von diesen Monstern getötet. Jetzt kann mir nur noch ihr Blut Frieden bringen.\n\nWenn Ihr mir helfen möchtet, dann sorgt für eine Ablenkung, damit ich mich näher an das Lager heranschleichen kann.\n\nEs wäre perfekt, wenn Ihr ein paar Mitglieder ihrer sogenannten \"Eisernen Donnerwache\" töten könntet.", sourceObjective = "Tötet 10 Mitglieder der Eisernen Donnerwache in den Knochen von Agurak im Frostfeuergrat.", completion = "Das habt Ihr gut gemacht, {class}.\n\nBevor wir jetzt unseren Angriff fortsetzen können, sollten wir in dem Gebiet nach Material suchen, das uns im Kampf nützen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[34067] = { id = 34067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seilsammlung", description = "Die Bändiger der Donnerfürsten verwenden solch dickes Seil bei der Zähmung ihrer gefährlichen Bestien.\n\nSpäher Ruk'gan könnte das und ein paar mehr davon vielleicht brauchen.", sourceObjective = "Sammelt 5 dicke Seile von den Bändigern der Donnerfürsten in den Knochen von Agurak.", progress = "Ich habe das Warten satt. Habt Ihr etwas gefunden, das uns bei unserem Überfall hilft, oder nicht?", completion = "Stricke? Soll ich etwa eine Schlinge knüpfen und die Donnerfürsten bitten, sich selbst aufzuhängen?\n\nMoment... da kommt mir eine Idee. Ja, ich glaube, mit den richtigen Materialien könnte das funktionieren.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[34068] = { id = 34068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rockhoof" }
quests[34069] = { id = 34069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Spitze treiben", description = "So ein Donnerfürstenspeer ist äußerst leicht und stabil.\n\nSpäher Ruk'gan könnte den und ein paar mehr davon vielleicht brauchen.", sourceObjective = "Sammelt 5 Donnerfürstenspeere in den Knochen von Agurak.", progress = "Was gibt's, {class}? Habt Ihr etwas für mich?", completion = "Hm, ja, diese Speere sehen ziemlich gut aus.\n\nNicht schlecht! Ich weiß genau, wozu die gut sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[34070] = { id = 34070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreht ihnen einen Strick draus", description = "Mit den Speeren und den Stricken, die Ihr besorgt habt, sind die Himmelsreiter der Donnerfürsten jetzt in unserer Reichweite. Sogar sie werden unseren Zorn zu spüren bekommen!\n\nIch habe das Seil an den Speer gebunden, den Ihr mir gebracht habt, und so eine Harpune hergestellt. Jagt damit die Himmelsreiter, die über dem ganzen Tal herumfliegen. Nehmt die Harpune und schleudert sie nach ihnen, wenn sie näherkommen. Wenn Ihr gut zielt, sollte der Speer mit den Widerhaken gut halten, sodass Ihr den Reiter geradewegs herunterreißen könnt!\n\nWenn Ihr zu schlecht zielt... na ja... versucht einfach, nicht daneben zu werfen.", sourceObjective = "Holt mit der Stachelharpune 5 Himmelsreiter der Donnerfürsten aus dem Sattel und tötet sie.", completion = "Gut gemacht, {name}! Ohne die Himmelsreiter wird es hier unten etwas ruhiger für uns. Behaltet Eure Waffe trotzdem in der Hand. Wir sind noch nicht mit ihnen fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[34072] = { id = 34072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totale Teer-störung", description = "Diese Bande Donnerfürsten wird von diesem Feigling General Vul'gath angeführt. Er versteckt sich in seiner Hütte und brüllt seinen Kämpfern die Befehle durch die Wände zu.\n\nWir werden ihm zeigen müssen, dass seine schwache Verteidigung nicht gegen die Frostwölfe bestehen kann!\n\nIch brauche für meinen Plan etwas Teer. Im Süden gibt es mehrere Teergruben, also holt ein paar Klumpen von dem Schlamm dort und bringt sie mir.", sourceObjective = "Sammelt 5 Klumpen klebrigen Teers von dem schwarzen Teer in den Knochen von Agurak.", progress = "Wir brauchen schleunigst den Teer, {name}! Macht schon!", completion = "Puh, stinken die! Nein, ich muss sie nicht sehen. Ich glaube Euch, dass Ihr genug habt.\n\nLegen wir los, bevor noch eine Patrouille der Donnerfürsten über mich stolpert.", sourceObjectiveStatus = "unverified-source-field" }
quests[34073] = { id = 34073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt sie nieder", description = "Jetzt können wir unseren Überfall starten, {name}!\n\nGeht hinunter nach Aguraks Ende und zerstört ihre Rylakeibrüter mit diesen Teerbomben.\n\nWährend Ihr beschäftigt seid, werde ich mich in ihr Lager schleichen und die nächste Phase unseres Angriffs vorbereiten. Trefft Euch dort mit mir, nachdem Ihr alles niedergebrannt habt.", sourceObjective = "Brennt die Inkubationskäfige der Donnerfürsten in Aguraks Ende nieder.", completion = "Gute Arbeit, {name}. Ich konnte den Aufruhr, den Euer Werk verursacht hat, nutzen, um mich in das Lager zu schleichen.\n\nJetzt bleibt nur noch eins zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34075] = { id = 34075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vul'gaths Ende", description = "Vul'gaths Zeit ist abgelaufen, {name}. Das Blut meiner Tochter klebt an seinen Händen. Jetzt werden wir unsere Hände in seines tauchen!\n\nZeigt keine Gnade und bringt ihn zu Fall!", sourceObjective = "Tötet General Vul'gath in Aguraks Ende.", completion = "Danke, {name}.\n\nIch wünschte, wir könnten ihn zurückholen, nur um ihn noch einmal zu töten, aber ich schätze, das eine Mal muss genügen.\n\nIch hoffe, der Geist meiner Kleinen wird jetzt Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34076] = { id = 34076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Begräbnisfelder" }
quests[34078] = { id = 34078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fällige Bezahlung für Dienstleistungen", description = "Ich will jetzt hier raus und ich werde nicht durch all diese Orcs rennen.\n\nZum Glück habe ich noch ein paar Raketenhühnchen dabei, die uns mit Stil zu Eurer Garnison zurückbringen werden! Lasst uns aufs Dach gehen und einen vernünftigen Platz zum Abheben suchen.", sourceObjective = "Bringt Gazlowe auf das Dach von Oberanführer Schwarzhammers Festung im Eisernen Belagerungswerk.", completion = "Ich sagte Euch doch, ich werde Wort halten!", sourceObjectiveStatus = "unverified-source-field" }
quests[34079] = { id = 34079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission erfolgreich abgeschlossen", description = "Die Donnerfürsten sind am Ende, {name}, und unsere Arbeit ist getan. Ich werde hierbleiben und über dieses Gebiet wachen.\n\nIhr solltet zu Unteroffizier Gil'nath zurückkehren. Ich bin sicher, er hat eine neue Aufgabe für Euch.", sourceObjective = "Sprecht mit Unteroffizier Gil'nath im Frostfeuergrat.", sourceObjectiveStatus = "unverified-source-field" }
quests[34087] = { id = 34087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in die Ferne", description = "Ein Verbündeter von Euch, Thaelin, hilft uns, der Eisernen Horde entgegenzutreten.\n\nEr behauptet, dass man mit dieser Vorrichtung den Feind ausspionieren kann und sogar über weite Entfernungen hören kann, was gesprochen wird.\n\nIch traue solchen Vorrichtungen nicht. Benutzt sie und lasst mich wissen, was Ihr seht.", sourceObjective = "Werft einen Blick durch Thaelins Beobachtikopter.", progress = "Werft einmal einen Blick durch Thaelins Beobachtikopter. Ich vertraue dieser Maschine nicht.", completion = "Orgrim führt die Eiserne Horde in Talador an... Jetzt kennen wir das Gesicht unseres Feindes.", sourceObjectiveStatus = "unverified-source-field" }
quests[34088] = { id = 34088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Eisen im Feuer", description = "Wir müssen die Truppen der Eisernen Horde vernichten, die unser Land befallen.\n\nFindet diejenigen, die unseren großartigen Wald besudeln, und zeigt ihnen die Hand der Gerechtigkeit.", sourceObjective = "Tötet 15 Mitglieder der Eisernen Horde bei der Rodung von Mor'gran.", completion = "Die Eiserne Horde nimmt keine Rücksicht auf die Wunder des Waldes. Im Tod werden sie Respekt lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34089] = { id = 34089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelware", description = "Die Eiserne Horde bewahrt Sprengladungen mitten in ihrem Holzfällerlager auf.\n\nWir müssen sie bergen, damit sie nicht gegen uns zum Einsatz kommen.\n\nIch werde Maraad im Auge behalten... Ich mache mir Sorgen, dass er in seiner Wut etwas Unbedachtes tut.", sourceObjective = "Sammelt 6 Sprengladungen der Eisernen Horde ein.", progress = "Habt Ihr die Sprengladungen der Eisernen Horde schon gefunden?", completion = "Ich denke, wir können diese Sprengladungen gegen die Eiserne Horde verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34090] = { id = 34090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thaelins Notlösung", description = "Diese Orcs stapeln furchtbar gern Dinge auf einen Haufen. Da kam mir eine Idee...\n\nIch habe dieses geniale Gerät für Euch gebaut! Wenn Ihr Euch einem Ziel nähert, wird es das anzeigen. Dann könnt Ihr es auslegen und es gibt ein richtig dickes, fettes kaBUMM!", sourceObjective = "Zerstört die Vorräte der Donnerfürsten, die Schwarzfelsschmiede und das Holzlager.", completion = "Nichts erwärmt das Herz so sehr wie eine gute Explosion.", sourceObjectiveStatus = "unverified-source-field" }
quests[34091] = { id = 34091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrangieren!", description = "Ketya Eisenschredder,\n\nEure neuen Eisenschredder sind eine Gefahr für unsere eigenen Soldaten.\n\nNehmt den Prototyp außer Betrieb und verwahrt ihn irgendwo, bis er wieder einwandfrei funktioniert.\n\nIch werde Ingenieur Trak damit beauftragen, ihn zu reparieren.\n\n– Orgrim Schicksalshammer", sourceObjective = "Tötet Ingenieur Trak und findet den ausrangierten Eisenschredder.", completion = "Der Prototyp eines Eisenschredders, was?! Ich wette, ich kann das Ding wieder zum Laufen bringen... die hatten Thaelin Schwarzamboss nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[34092] = { id = 34092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Maßnahmen", description = "Wir haben Teron'gors Truppenlager ausfindig machen können, aber seine Streitkräfte sind bereits viel stärker als alles, dem wir uns jemals stellen mussten. Wir müssen einen Vorteil für uns finden und zwar schnell.\n\nDie verfluchten Geister der Ango'roshoger, unsere uralten Feinde, suchen die nahen Ruinen heim. Geht dorthin und findet das Zauberbuch der Ango'rosh und den Zauberfolianten der Bindung.\n\nVollzieht das beschriebene Ritual an ihrem Altar, um den Fluch aufzuheben und ersucht sie um ihre Hilfe.\n\nEs ist unwahrscheinlich, dass es klappt, aber uns bleibt nichts anderes übrig.", sourceObjective = "Bergt das Zauberbuch der Ango'rosh und den Zauberfolianten der Bindung und führt in den Ruinen der Ango'rosh das Ritual am Altar der Ango'rosh durch.", progress = "War es Euch möglich, Euch der Hilfe der Ango'rosh zu versichern?", completion = "Ihr strahlt die Macht der Ango'rosh aus!\n\n<Restalaan lächelt.>\n\nJetzt wird es Zeit, dass wir Teron'gor direkt in seiner Zuflucht konfrontieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[34093] = { id = 34093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Spitze treiben", description = "Diese Donnerfürsten, die über uns kreisen, sind ein Problem, {name}.\n\nSie fliegen mit ihren erbärmlichen Rylaks gemächlich über das Tal und glauben, sie könnten völlig ungefährdet ihre Speere auf unsere Köpfe niederregnen lassen. Wir müssen ihnen zeigen, dass sie nirgends vor der Rache der Frostwölfe sicher sind!\n\nIch habe einen Plan, wir werden jedoch einige Materialien sammeln müssen. Durchsucht das Tal nach Speeren von ihnen, die noch intakt sind. Ich glaube, fünf sollten reichen.", sourceObjective = "Sammelt 5 Stachelspeere der Donnerfürsten in den Knochen von Agurak.", sourceObjectiveStatus = "unverified-source-field" }
quests[34094] = { id = 34094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Band mit X Seiten", description = "In dem Cockpit des Schredders war ein Handbuch eingeklemmt, aber da fehlen viele Seiten. Wenn wir die fehlenden Seiten des Handbuchs finden, wette ich meinen dicken Onkel, dass ich den Prototypen des Schredders wieder flott bekomme.\n\nIch hätte schwören können, dass ich einige der Seiten irgendwo im Belagerungsposten Archenon habe herumflattern sehen. Vielleicht tragen die Orcs sie mit sich herum.", sourceObjective = "Nehmt Orcs beim Belagerungsposten Archenon 20 Seiten der Bedienungsanleitung ab.", progress = "Habt Ihr die Seiten gefunden? Diese Anleitungen sind lächerlich lang.", completion = "Ich habe mich schon gewundert, warum die Anleitung so dick war... die schreiben in echt großen Buchstaben!", sourceObjectiveStatus = "unverified-source-field" }
quests[34095] = { id = 34095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Eiserner Hand", description = "Die Orcs sind nicht die einzige Bedrohung. Sie haben immer noch Belagerungswaffen mit erheblicher Durchschlagskraft.\n\nSie wurden bereits gegen Tuurem eingesetzt und wir dürfen nicht zulassen, dass sie weiterhin verwendet werden.\n\nSabotiert die Belagerungswaffen und benutzt dafür die Sprengladungen, die Ihr im Holzfällerlager eingesammelt habt.", sourceObjective = "Zerstört 6 Belagerungsmaschinen der Eisernen Horde.", completion = "Sie werden diese Waffen nicht mehr gegen uns verwenden können, wenn wir Tuurem angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34096] = { id = 34096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auge um Spionenauge", description = "Ich werde den Schredderprototypen sofort wieder funktionsfähig machen.\n\nWerft einen Blick durch meinen Beobachtikopter. Dann seht Ihr, was Euch bevorsteht...", sourceObjective = "Werft einen Blick durch Thaelins Beobachtikopter.", completion = "Das sind 'ne Menge Orcs, was? Ich bin froh, dass ich hier am Herumbasteln bin statt in der Hitze des Gefechts.", sourceObjectiveStatus = "unverified-source-field" }
quests[34097] = { id = 34097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Schreddern geboren", description = "Es ist mir gelungen, dass der Schredderprototyp auf den meisten Zylindern wieder läuft.\n\nJunge, werden die überrascht sein, wenn Ihr sie mit ihrer eigenen Maschine niedertrampelt!\n\nIch kann es kaum erwarten, Euch aus sicherer Entfernung durch den Beobachtikopter zuzusehen.", sourceObjective = "Tötet in Tuurem 100 Mitglieder der Eisernen Horde mit dem Eisenschredder.", completion = "– FEINDE ELIMINIERT –", sourceObjectiveStatus = "unverified-source-field" }
quests[34098] = { id = 34098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstruierter Untergang", description = "– MUTTER ENTDECKT. WARNUNG! WARNUNG! –", sourceObjective = "Besiegt Ketya Eisenschredder.", completion = "Die Schreie Eurer Feinde waren Musik in meinen Ohren. Das Volk von Tuurem ist gerächt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34099] = { id = 34099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Shattrath", description = "Um die Eiserne Horde aufzuhalten, müssen wir Vorurteile überwinden und zusammenarbeiten... und sei es nur zu diesem Zweck.\n\nHorde, Allianz, Vergangenheit, Gegenwart... All das ist bedeutungslos angesichts dieses Feinds.\n\nGemeinsam werden wir Shattrath zurückerobern... oder bei dem Versuch sterben.", sourceObjective = "Vertreibt die Eiserne Horde aus Shattrath.", completion = "Maraad ist tot... aber wir müssen weitermachen. Ich werde nicht zulassen, dass dieses Opfer umsonst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[34101] = { id = 34101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Aruumel's Worn Mace" }
quests[34102] = { id = 34102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal der Herausforderung", description = "Während Ihr Euch das Banner der Frostwölfe anseht, erinnert Ihr Euch an die Mühen, die Euch und die Frostwölfe bis zu diesem Punkt gebracht haben.\n\nRuk'gan hat in seinem Kampf gegen die Donnerfürsten sehr gelitten und würde ein besonderes Zeichen des Widerstands sicher zu schätzen wissen.\n\nAls das Banner im Wind raschelt, kommt Euch die Idee, die Gegner der Frostwölfe mit ihrem Banner zu kennzeichnen.", sourceObjective = "Verwendet die vom Kampf gezeichneten Frostwolfbanner bei 6 Leichnamen von Orcs der Donnerfürsten in Aguraks Ende.", completion = "Gute Arbeit, {name}!\n\nDie Banner der Frostwölfe stolz über unseren zerschmetterten Feinden erhoben zu sehen, erfüllt mich mit Stolz!\n\nSollen sie auf ewig den Zorn der Frostwölfe fürchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[34103] = { id = 34103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kil'uun", description = "Ich habe ein Kopfgeld auf einen Vogel ausgesetzt, Kommandant. Ja, ganz recht, auf einen Vogel.\n\nDas Viech ist nämlich riesig und wurde zuletzt einen Steinwurf entfernt vom Lager der Horde in dem südlich gelegenen Wald gesichtet. Im Volksmund wird der monströse Vogel Kil'uun genannt.\n\nWenn Ihr ihn erlegen und seinen Schnabel als Trophäe zurückbringen würdet, wären Euch ein oder zwei Säcke Gold gewiss!", sourceObjective = "Erlegt Kil'uun und bringt seinen Schnabel zu Patrick Messer.", progress = "Konntet Ihr den Vogel aufspüren, Kommandant?", completion = "Ich habe keine Ahnung, wie Ihr das Biest so nah am Lager der Horde jagen konntet, Kommandant, aber Ihr habt Eure Sache ganz offensichtlich gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[34104] = { id = 34104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Hilaani", description = "O'Riley möchte unsere Arbeiter für ihre gute Leistung mit einem Flussbestienfestessen belohnen.\n\nDamit Ihr nicht tagelang Flussbestien erschlagen müsst, habe ich einen Vorschlag, Kommandant. In dem See südlich von hier lebt angeblich eine riesige Flussbestie namens Hilaani, die das gesamte Fort doppelt satt machen dürfte.\n\nWenn Ihr davon ein paar dicke Scheiben besorgen könntet, wären die Männer bestimmt dankbar.", sourceObjective = "Tötet Hilaani und bringt das Flussbestienfleisch zu Patrick Messer.", progress = "Hattet Ihr Zeit, Hilaani zu töten?", completion = "Danke, Kommandant! Morgen werden die Arbeiter Lieder über Eure Großzügigkeit singen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34105] = { id = 34105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ra'tok der Hammer", description = "Kommandant, ich habe ein Problem, bei dem ich Eure Hilfe gebrauchen könnte.\n\nUnsere Soldaten haben eine Kriegerin der Eisernen Horde entdeckt, die bei den Klippen hier in der Nähe herumschlich. Wir vermuten, dass sie die Truppen der Horde an strategisch wichtige Punkte lenken will, sobald sie an der Orunaiküste gelandet sind.\n\nIch müsste mir um die Sicherheit unseres Forts weniger Sorgen machen, wenn Ihr sie ausschalten könntet.", sourceObjective = "Erledigt Ra'tok den Hammer an der Orunaiküste.", completion = "Man bejubelt weithin Euren Ruhm, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[34106] = { id = 34106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ra'tok der Hammer", description = "Die Eiserne Horde kennt keine Ehre. Sie ekelt mich an.\n\nWir haben einen ihrer Leutnants an den Klippen unfern unseres Stützpunkts beobachtet. Ich glaube, dass sie unsere Bewegungen nachverfolgt, um einen Angriff von der Orunaiküste vorzubereiten.\n\nIch weiß wohl, dass Ihr viel zu tun habt. Doch wenn Ihr die Zeit habt, dürfte Euer Beitrag der Sicherheit unserer Stellung zum Vorteil gereichen.", sourceObjective = "Tötet Ra'tok den Hammer an der Orunaiküste.", completion = "Ich wusste, dass Ihr sie erledigen würdet. Kein Mitglied der Eisernen Horde ist vor Eurem Zorn sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[34107] = { id = 34107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Hilaani", description = "Wir brauchen mehr Fleisch, Kommandant.\n\nSicher fragt Ihr Euch, was mit all dem Fleisch hinter mir ist, aber genau da liegt das Problem. Es wird gerade mal einen Tag reichen, wenn wir Glück haben.\n\nIm See südlich von hier lebt eine Flussbestie, die im Volksmund Hilaani genannt wird. Sie ist riesig, der reinste Fleischberg!\n\nWenn Ihr die Bestie erlegt und mir ihr Fleisch bringt, werden Eure Wölfe gut versorgt sein.", sourceObjective = "Erschlagt Hilaani und bringt das Flussbestienfleisch zu Bestienmeister Tagh.", progress = "Schön, Euch zu sehen, Kommandant.", completion = "Ist das das, was ich denke, dass es ist? Zu freundlich, Kommandant!", sourceObjectiveStatus = "unverified-source-field" }
quests[34108] = { id = 34108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kil'uun", description = "Dieser verdammte Vogel!\n\nAlle paar Stunden fliegt er hier vorbei und keiner der Idioten hält ihn auf.\n\n\"Der Wahnsinn funkelt in seinen Augen\", jammern sie. Pah!\n\nKommandant, dieser Vogel bringt mich noch um den Verstand. Falls Ihr ihn seht, könntet Ihr ihm seinen dämlichen Kopf abschlagen und ihn mir bringen?\n\nDann würde ich mich besser fühlen.", sourceObjective = "Bringt Kil'uuns Schnabel zu Bestienmeister Tagh.", progress = "Falls Ihr die Kreatur tötet, werde ich meinen Erstgeborenen nach Euch benennen.", completion = "Hoch lebe {name}! Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[34110] = { id = 34110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Girl 1 Found" }
