quests[34119] = { id = 34119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Guy 2 Found" }
quests[34122] = { id = 34122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerdiplomatie", description = "Sie mögen vielleicht Geister sein, aber die Ango'rosh sind immer noch Oger. Selbst mit ihren Büchern in der Hand werden sie kein Respekt vor euch haben, bis Ihr Euch als würdig erwiesen habt. Und um das zu erreichen, gibt es nur eine Möglichkeit.\n\nIhr müsst sie töten.\n\nTötet so viele Geister der Ango'rosh und ihre Haustiere wie möglich, wenn Ihr in den Ruinen seid.", sourceObjective = "Tötet 10 Ango'rosh in den Ruinen der Ango'rosh.", completion = "<Liadrin lächelt.>\n\nIch wusste, dass wir einer Meinung sein würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34123] = { id = 34123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Donnerpass", description = "Wir haben keine Zeit, unsere Gefallenen zu betrauern oder unsere Wunden zu lecken. Eure Späher haben bereits berichtet, dass eine riesige Armee der Eisernen Horde auf dem Weg durch den Donnerpass ist.\n\nAm besten lasst Ihr Eure Garnisonsstreitkräfte dieses Gebiet sichern, während wir beide uns mit den restlichen Frostwölfen zum Pass östlich von hier begeben.\n\nEs wird Zeit, dieser Eisernen Horde zu zeigen, wozu ein vereinter Frostwolfklan fähig ist.", sourceObjective = "Sprecht mit Lokra an der Wolfswehr.", completion = "Was bin ich froh, Euch zu sehen! Unser Klan hat schon einiges durchgemacht, aber die schiere Größe der Armee, die auf uns zu marschiert, stellt alle bisherigen Bedrohungen in den Schatten.\n\nWir brauchen Eure Erfahrung.", sourceObjectiveStatus = "unverified-source-field" }
quests[34124] = { id = 34124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht am Donnerpass", description = "Die Armee der Eisernen Horde, die jetzt gerade den Donnerpass hinuntermarschiert, ist zehnmal so groß wie unsere.\n\nDurotan zieht unsere Streitkräfte am Eingang des Passes zusammen. Er tut, was er kann, um eine Verteidigung auf die Beine zu stellen, aber für einen Krieg von solchem Ausmaß sind wir Frostwölfe nicht geschaffen.\n\nEr wird Eure Hilfe benötigen.\n\nBitte, geht zu ihm.", sourceObjective = "Verteidigt den Frostfeuergrat vor der Eisernen Horde.", completion = "Das war ein teurer Sieg und eine schmerzhafte Lektion. Wir haben beschlossen, die Eiserne Horde zurückzuweisen und so weiterzuleben, wie wir es immer getan haben. Allerdings erkenne ich jetzt, dass sie diese Neutralität niemals anerkennen werden.\n\nIch werde nicht darauf warten, dass die Eiserne Horde ihre Streitkräfte verstärkt. Wir werden an Eurer Seite kämpfen und die Eiserne Horde in die Knie zwingen.\n\nKommandant, die Frostwölfe sind bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[34127] = { id = 34127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mother Bloodtusk" }
