quests[34143] = { id = 34143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Kal'rak the Drunk" }
quests[34144] = { id = 34144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung für das Licht", description = "Die Agenten der Finsternis lauern überall, um diese Welt mit Schatten zu überziehen. Koste es, was es wolle. Es ist unsere Aufgabe, das Licht zu schützen und die Balance sicherzustellen.\n\nIhr verfügt über die notwendige Macht, um Teron'gors Dämonenschergen ein für alle Mal zu vernichten. Schickt sie zurück in den Wirbelnden Nether!", sourceObjective = "Tötet 15 Dämonen in Gul'rok.", completion = "Ich kann schon spüren, wie das Licht über die Finsternis triumphiert. Wir haben es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
