quests[34153] = { id = 34153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 04" }
quests[34154] = { id = 34154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Unbekannt", description = "Teron'gor und Gul'dan verließen gerade das Portal, als ich ankam... und ich... ich weiß, dass ich ihnen nicht gewachsen bin.\n\nIch werde das Portal so lange offen halten wie ich kann, doch es liegt an Euch, ihnen den Todesstoß zu versetzen.\n\nUnser Schicksal liegt in Euren Händen, {name}.", sourceObjective = "Vernichtet Mongrethod in den Trümmern von Xandros.", completion = "Teron'gor und Gul'dan... sie haben alle abgeschlachtet...\n\n...und dann, dann... verschwanden sie einfach... in die Schatten...\n\nWoher wussten sie nur, wohin sie gehen mussten?", sourceObjectiveStatus = "unverified-source-field" }
quests[34155] = { id = 34155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 06" }
quests[34157] = { id = 34157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Herz des Wahnsinns", description = "{name}, Nyami ist losgezogen, um Teron'gor selbst auszuschalten, wie sie sagte!\n\nIhr müsst sie finden. Alleine hat sie keine Chance gegen ihn.\n\nIch selbst muss hier bleiben und unsere Truppen neu organisieren, falls ein erneuter Angriff bevorsteht. Ich zähle auf Euch.", sourceObjective = "Sprecht mit Seelenbinderin Nyami am Sitz der Verderbtheit in Gul'rok.", completion = "Ihr müsst Euch beeilen... Teron'gor ist gerade geflüchtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[34160] = { id = 34160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Nixxie the Goblin" }
quests[34162] = { id = 34162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Icklarv" }
quests[34163] = { id = 34163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckt in den Schatten", description = "<Die Stimme von Teron'gor dringt in Euren Verstand.>\n\nMeine Diener, die Auchenai dürfen nichts von unserem letzten Schritt erfahren. Verwendet die Schattenkugeln, die Gul'dan uns gegeben hat, um Gul'rok in Dunkelheit zu hüllen.\n\nBereitet die Truppen vor. Wir werden auf meinen Befehl nach Auchindoun marschieren. Wir werden die Seelen der Draenei fressen und unsere dämonischen Verbündeten in diese Welt holen!\n\n<Die Zerstörung der Schattenkugeln wäre eine große Hilfe für die Verteidiger von Auchindoun.>", sourceObjective = "Zerstört die drei Schattenkugeln in Gul'rok.", sourceObjectiveStatus = "unverified-source-field" }
quests[34164] = { id = 34164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bücherverbrennung", description = "Ich bitte Euch, {name}... Ich habe nicht viel Zeit.\n\nDer Schattenrat hat zugestimmt, sich von Teron'gor und seinen Hexenmeistern in Dämonen verwandeln zu lassen!\n\nIch glaube, dass die schattengeborenen Dementoren Zauber verwenden, die sie von Gul'dan erhalten haben, um die dämonischen Orcs noch stärker zu machen. Nehmt ihnen die Zauberbücher ab und werft sie hier in das Feuer neben mir... Das wäre ein schöner Anblick im Angesicht des Todes.", sourceObjective = "Erbeutet 3 Zauberbücher des Schattenrates und verbrennt sie im Feuer bei Kor'thos Zorndämmerung in Gul'rok.", progress = "Ja?", completion = "Ich danke Euch... Und tötet noch ein paar mehr von ihnen auf dem Weg nach draußen, wenn Ihr könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[34165] = { id = 34165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cro Fleshrender" }
