quests[34192] = { id = 34192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ganz und Goren-icht gut für uns", description = "Der verlassene Minenschacht ist von Goren überrannt worden! Sie scheinen die Befehle eines großen Anführers tief unten in der Mine zu befolgen. Wenn Ihr ihn ausschalten könnt, werden sich die anderen vielleicht zurückziehen.\n\nUnd wenn Ihr erst die Goren erledigt habt, könnten wir diese Mine wieder in Gang bringen!", sourceObjective = "Tötet Steinzahn in der Garnisonsmine.", completion = "Gute Arbeit, {name}! Dann wollen wir diese Mine mal wieder in Betrieb nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34193] = { id = 34193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Garten aufräumen", description = "Diese Höhle hat das perfekte Klima, um darin Kräuter für unsere Garnison anzubauen. Es gibt da nur ein kleines Problem: all diese verdammten Knabbertiere!\n\nIch möchte, dass Ihr sie vertreibt, dann können wir damit beginnen, diesen Garten zu bepflanzen.", sourceObjective = "Tötet 8 Frostwallnager.", completion = "Gute Arbeit, {name}! Wir sollten sofort damit anfangen, den Garten zu bepflanzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34194] = { id = 34194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Hilfe", description = "Wir haben hier einen geeigneten Angelplatz, aber kein Köder scheint zu funktionieren! Wir brauchen einen einheimischen Angler, der sich mit den Fischen in dieser Gegend auskennt. Folgt dem Ufer nach Nordwesten seht, ob Ihr an der Küste jemanden finden könnt.", sourceObjective = "Findet einen ortskundigen Fischer, der uns zur Seite stehen kann.", progress = "Habt Ihr jemanden gefunden?", completion = "Jetzt könnt Ihr zeigen, wie nützlich Ihr seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[34195] = { id = 34195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 16" }
