quests[34208] = { id = 34208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Lo'marg Kieferbrecher" }
quests[34209] = { id = 34209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicheres Geleit", description = "Es hat sich eine äußerst wichtige Angelegenheit ergeben. Während Ihr unterwegs wart, hat mich Erzmagier Khadgar kontaktiert.\n\nEr untersucht dämonische Einflüsse im Norden.\n\nDie Frostwölfe werden Khadgar nicht akzeptieren, da er ein Mensch ist. Auch eine Nachtelfe wie ich wird dort nicht mit offenen Armen empfangen werden... Euch hingegen könnte es gelingen, sie von unserer Sache zu überzeugen, wenn Ihr für den Erzmagier bürgt.\n\nIch werde außerhalb von Throm'var auf den Frostwindklippen auf Euch warten.", sourceObjective = "Trefft Euch mit Cordana Teufelsang außerhalb von Throm'var auf den Frostwindklippen.", completion = "Danke, dass Ihr gekommen seid, {name}. Der Erzmagier und ich brauchen Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
