quests[34215] = { id = 34215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 22" }
quests[34216] = { id = 34216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichere Passage", description = "Als Mensch und als Nachtelfe werden der Erzmagier und ich bei den Orcs des Frostwolfklans wahrscheinlich nicht allzu freudig begrüßt werden.\n\nIhr müsst uns beim Scharfseher von Throm'var einführen.\n\nEs gibt eine Menge zu besprechen. Soll ich Euch auf dem Weg zum Dorf auf den neuesten Stand bringen?", sourceObjective = "Hört Euch Cordana Teufelsangs Geschichte an.", progress = "Ihr ehrt uns mit Eurer Anwesenheit.", completion = "Wolfsbruder, uns haben bereits Geschichten über Eure Taten in Wor'gol erreicht. Euch ist der ewige Respekt der Frostwölfe sicher.\n\nSagt, wer sind diese Fremden, die Ihr mitgebracht habt, und was ist so dringend?", sourceObjectiveStatus = "unverified-source-field" }
quests[34217] = { id = 34217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blon'sky Beat", description = "Grulk will nicht mutiert werden. Grulk kein Monster wie Blon'sky! Blon'sky böse... hat Mutation für Macht gewählt!\n\nhr geht nach Grommar? Haut Blon'sky bevor er Unschuldigen wehtut. Das würde Grulk glücklich machen!", sourceObjective = "Besiegt Blon'sky.", sourceObjectiveStatus = "unverified-source-field" }
quests[34218] = { id = 34218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 23" }
