quests[34225] = { id = 34225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreaturschatz: Eiserner Faulpelz" }
quests[34227] = { id = 34227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was getan werden muss", description = "Ich glaube, wir haben diese dämonische Verderbnis, von der Eure Freunde sprechen, gesehen.\n\nDie Wolfsmutter war in letzter Zeit nicht sie selbst. Jetzt hat ihr Rudel sie umzingelt.\n\nDie Wölfe wollen unsere Jäger beschützen und lassen sie deswegen nicht an die Wolfsmutter heran. Euch werden sie aber wahrscheinlich nicht aufhalten.\n\nWenn die Alphamutter mit dieser teuflischen Energie infiziert ist, muss sie getötet werden.\n\nIhr würdet den Frostwölfen eine große Ehre erweisen, wenn Ihr mit ihrem Leichnam zurückkehren und ihr ein ordentliches Begräbnis zukommen lassen würdet.", sourceObjective = "Holt die Überreste der Wolfsmutter und begrabt sie auf dem Friedhof außerhalb des nördlichen Throm'var.", completion = "Es ist bedauerlich, dass es jene gibt, die so edle Kreaturen verderben wollen.\n\nIhr habt ihrer Familie wieder einmal Ehre erwiesen, {name}. Das werden sie nicht vergessen.\n\nEs wird jetzt Zeit, den Kampf direkt zum Schattenrat zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34228] = { id = 34228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Knäuel Würmer", description = "Auf einer Aufklärungsmission ist mir aufgefallen, dass der Großteil der Frostwindklippen von einer eigenartigen Wurmart befallen ist.\n\nDas Schlimmste dabei ist, dass sich diese Dinger durch den Boden wühlen und einen dann wie aus dem Nichts anspringen.\n\nIch habe gesehen, wie die Würmer die Frostwölfe und andere Wildtiere in der Ödnis angegriffen haben. Ich bin sicher, die Orcs würden es gerne sehen, wenn Ihr helfen könntet.", sourceObjective = "Tötet 15 Eiswüstenfelswürmer.", completion = "Wir haben diese Kreaturen seit Jahrzehnten nicht mehr gesehen.\n\nIhr plötzliches Erscheinen hängt sicher mit dem Erdbeben zusammen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34229] = { id = 34229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schläferin ist erwacht", description = "Irgendetwas hat die große Shui Halad aufgeweckt. Sie bringt den Boden zum Beben.\n\n<Der Scharfseher zeichnet einen Zauberschutz in die Luft und fährt dann fort.>\n\nVielleicht sind diejenigen, die den großen Wurm gestört haben, dieselben, denen Eure Freunde nachspüren?\n\nWie auch immer, Shui Halad muss die ewige Ruhe finden, bevor ihr Wüten den ganzen Norden in den Ozean stürzen lässt.", sourceObjective = "Tötet Shui Halad.", completion = "Ich habe von diesen seltsamen fahlen Orcs gehört, die Ihr gesehen habt. Das klingt nach den Kriegssängern von Nagrand. Aber nein, das kann nicht sein...\n\nWas den Oger angeht, sein Name ist Cho'gall. Ihr solltet ihn töten, wenn sich die Gelegenheit bietet. Er hinterlässt nichts als Zerstörung.", sourceObjectiveStatus = "unverified-source-field" }
quests[34230] = { id = 34230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augenblick mal!", description = "Die Wolfsmutter war mit dämonischer Magie infiziert. Der Schattenrat muss gehofft haben, die Verderbnis so auf die anderen Frostwölfe und danach auf Throm'var auszudehnen.\n\nDie Jäger berichten, dass sie unten auf dem Eisschrammenfriedhof im Westen grün glühende Augen gesehen haben. Wir wissen beide, was das bedeutet.\n\nIch habe eine Idee... Wir werden die \"Augen\" des Schattenrats gegen ihn selbst einsetzen, um seine Basis zu entdecken. Wir brauchen dazu nur den allsehenden Ring des obersten Hexenmeisters.", sourceObjective = "Besorgt den allsehenden Ring von Ogzor dem Nekrothurgen.", progress = "Der allsehende Ring. Habt Ihr ihn?", completion = "Ja... das wird funktionieren. Setzen wir die Magie des Schattenrats gegen ihn selbst ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[34231] = { id = 34231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Giant Snake" }
quests[34232] = { id = 34232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Rooks Angelzubehör" }
quests[34233] = { id = 34233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Krug gealterten Eisenweins" }
quests[34234] = { id = 34234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahltag", description = "Wir dachten, dass wir hinter Blattschattens Tarnung sicher wären.\n\n<Verteidiger Kaluud wischt sich das Blut aus dem Gesicht.>\n\nIrgendjemand muss den Truppen des Schattenrates verraten haben, wie man sie deaktivieren kann. Zuerst konnten wir sie noch aufhalten...\n\nDie meisten Bewohner der Stadt fielen dem Angriff zum Opfer. Bitte, Ihr müsst unsere Gefallenen rächen. Befreit Telmor ein für alle Mal von diesen Invasoren!", sourceObjective = "Eliminiert 12 Truppen des Schattenrates in Telmor.", completion = "Ausgezeichnet. Jetzt sind die Splitter endlich wieder vereint!", sourceObjectiveStatus = "unverified-source-field" }
quests[34235] = { id = 34235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Leuchtende Muschel" }
quests[34236] = { id = 34236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Amethylkristall" }
quests[34238] = { id = 34238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Vesperdose des Vorarbeiters" }
quests[34239] = { id = 34239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Schatz von Tuurem" }
quests[34240] = { id = 34240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transportplan", description = "Ihr habt Euch schon oft in der Schlacht bewiesen, {name}. Wie Ihr wisst, könnten sich überall um Auchindoun herum Truppen des Schattenrates aufhalten, auch in der Nähe von Telmor.\n\nTuulanis Kräfte als Seelenpriesterin haben sich noch nicht vollständig entwickelt. Sie ist noch nicht in der Lage, den Splitter ganz allein zu bewachen. Ich möchte, dass Ihr Euch nach Telmor begebt und ihr dabei helft, den Splitter sicher nach Auchindoun zu bringen.", sourceObjective = "Sprecht mit Seelenbinderin Tuulani außerhalb von Telmor.", completion = "Hier ist es nicht sicher. Der Schattenrat hat bereits die Stadt eingenommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[34241] = { id = 34241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Gorgrond Treasure 12" }
quests[34242] = { id = 34242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transportplan", description = "Ihr habt Euch schon oft in der Schlacht bewiesen, {name}. Wie Ihr wisst, könnten sich überall um Auchindoun herum Truppen des Schattenrates aufhalten – auch in der Nähe von Telmor.\n\nIch möchte, dass Ihr Euch in Telmor Seelenbinderin Tuulani anschließt und ihr dabei helft, den Kristall sicher nach Auchindoun zu bringen. Bei dieser Sache kann ich mich nur auf Euch verlassen.", sourceObjective = "Sprecht mit Seelenbinderin Tuulani außerhalb von Telmor.", completion = "Hier ist es nicht sicher. Der Schattenrat hat bereits die Stadt eingenommen!", sourceObjectiveStatus = "unverified-source-field" }
