quests[34260] = { id = 34260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Minenlore von Aruuna" }
quests[34261] = { id = 34261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Keluus Habseligkeiten" }
quests[34262] = { id = 34262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Minenlore von Aruuna" }
quests[34263] = { id = 34263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Purer Kristallstaub" }
quests[34264] = { id = 34264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seilsammlung", description = "Keiner der Donnerfürsten kann meinem Zorn entrinnen! Wir benötigen etwas, um sie aus der Luft zu holen, damit sie mit unseren Klingen Bekanntschaft machen können.\n\nIhre Bändiger sollten Seile bei sich tragen, da sie es für den Umgang mit ihren Bestien benötigen. Tötet sie, und wenn sie brauchbare Seile bei sich haben, bringt sie mir.", sourceObjective = "Sammelt 5 dicke Seile von den Bändigern der Donnerfürsten in den Knochen von Agurak.", progress = "Ich habe das Warten satt. Habt Ihr etwas gefunden, das uns bei unserem Überfall hilft, oder nicht?", completion = "Stricke? Soll ich etwa eine Schlinge knüpfen und die Donnerfürsten bitten, sich selbst aufzuhängen?\n\nMoment... da kommt mir eine Idee. Ja, ich glaube, mit den richtigen Materialien könnte das funktionieren.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[34271] = { id = 34271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal Gordawgs", description = "Die riesige Kreatur, die zwischen uns und der inneren Kammer steht, ist der große Zorn, den wir auf den Thron der Elemente zurückbringen wollten.\n\nGordawg ist jetzt gefesselt, ein Sklave der Fahlen und ihres mysteriösen Meisters. Mein Herz ist voller Trauer, eine solch großartige Kreatur als willenlosen Sklaven des Bösen sehen zu müssen.\n\nJetzt gibt es kein Zurück mehr. Um weiterzukommen, müssen wir an Gordawg vorbei.\n\nAuch wenn es mich schmerzt: Wir müssen Gordawg töten.\n\nSobald die Tat vollbracht ist, bringen wir das Herz des Zorns zum Thron der Elemente.", sourceObjective = "Beschafft das Herz des Zorns.", progress = "Was ist mit Gordawg? Hat der große Zorn endlich seine Ruhe gefunden?", completion = "Gordawg war ein mächtiger Verbündeter. Die Elemente werden den Verlust des Zorns betrauern. Aber der Tod war die einzige Möglichkeit. Gordawg hätte nicht Sklave des Bösen bleiben wollen.\n\nGordawg weilt zwar nicht mehr unter uns, doch ist das Herz eines Zorns ewig und unzerbrechlich. Eines Tages wird dieses leuchtende Herz in einem neuen Erdzorn Gestalt annehmen.\n\nSo ist der Lauf des Lebens auf dem Elementarplateau.", sourceObjectiveStatus = "unverified-source-field" }
quests[34276] = { id = 34276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Rostiger Tresor" }
quests[34277] = { id = 34277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt den Zulauf", description = "Der Schattenrat wird unten auf dem Friedhof magische Kreise einrichten. Es reicht nicht aus, seine Mitglieder einfach zu töten, wir müssen auch ihre teuflischen Hilfsmittel vernichten.\n\nWenn Ihr die Kreise zerstört, stoppt Ihr auch den Zulauf an Dämonen, die sie in die Knochen der Toten beschwören.", sourceObjective = "Zerstört 7 Beschwörungskreise.", completion = "Wir hätten sie alle direkt am Anfang am Dunklen Portal umbringen sollen, ohne Rücksicht auf die Folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34278] = { id = 34278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweihung der Toten", description = "Diese dreckigen Hexenmeister entweihen die Toten auf dem Friedhof!\n\n<Der Scharfseher erzittert, als seine Selbstbeherrschung ins Wanken gerät.>\n\nICH WILL SIE TOT SEHEN!\n\nVernichtet die Nekrophyten. Vernichtet ihre dämonischen Abscheulichkeiten.", sourceObjective = "Tötet 15 Nekrophyten und Teufelswölfe.", completion = "Für das, was sie getan haben, ist das nicht genug.\n\n{name}, wenn Ihr ihre Basis findet, hinterlasst nichts als verbrannte Erde.", sourceObjectiveStatus = "unverified-source-field" }
quests[34279] = { id = 34279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Blook", sourceObjective = "Blook hat noch nie gesiegt.\n\nBlook folgt ab jetzt kleinem Mann. Blook will lernen, wie man mehr Leute besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[34280] = { id = 34280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles wird aufgedeckt", description = "Sagt mir, wenn Ihr bereit seid.\n\nWir werden die Macht des Ringes anrufen, um eins ihrer \"Augen\" zu beschwören. Damit werden wir herausfinden, wo sich der Schattenrat befindet und was er wirklich vorhat.", sourceObjective = "Spioniert den Schattenrat aus.", progress = "Wir müssen den allsehenden Ring einsetzen, um den Schattenrat zu finden und seine Pläne zu enthüllen.", completion = "Gul'dan ist dort! Wir müssen uns schnell in Bewegung setzen, um ihn zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34281] = { id = 34281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Ketten befreit", description = "Die haben mich wirklich ganz schön verprügelt und ich habe höllische Kopfschmerzen. Aber ich werde überleben. Ich muss allerdings aus diesen Ketten raus.\n\nKönntet Ihr den Schlüssel für mich besorgen? Ein großer Oger namens Nub hat ihn, er ist auf der anderen Seite der Terrasse.", sourceObjective = "Holt den Fesselschlüssel der Blutschläger und befreit Owynn Graddock.", progress = "Macht Euch um mich keine Sorgen. Ich werde hier sitzen und meine Wunden versorgen.", completion = "Ohne diese Steinkugel fühle ich mich gleich besser!", sourceObjectiveStatus = "unverified-source-field" }
quests[34284] = { id = 34284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Die Suche nach Owynn Graddock", description = "Kommandant, ich habe schlechte Neuigkeiten.\n\nAgent Graddock war auf einer Mission zur Überwachung der Blutschläger unterwegs und hat seine Zeitvorgabe für die Rückmeldung nicht eingehalten.\n\nEtwas stimmt nicht, {name}.\n\nWenn Owynn gefangen genommen wurde, haben sie ihn vielleicht mit ihren Sklaven weggesperrt.\n\nGeht hinüber zu den Steinzornklippen und versucht ihn zu finden.", sourceObjective = "Begebt Euch in die Steinzornklippen des Frostfeuergrats und sucht nach Owynn Graddock.", completion = "Da brat mir doch einer einen Gnom! Bin ich froh, Euch zu sehen! Ich hatte auf Rettung gehofft, aber ich hatte nicht erwartet, dass der Chef höchstpersönlich hier auftaucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[34285] = { id = 34285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufrüstung", description = "Als ich gefangen genommen wurde, nahmen sie mir meine Ausrüstung weg und ließen mir nur Lumpen. Mein Streitkolben wird zum Steinebrechen verwendet. Sie nehmen sogar meinen besten Dolch als Gabel! Ich will gar nicht wissen, was mit meiner Rüstung passiert ist. Ich hoffe nur, sie ist immer noch einsatzbereit.\n\nIch werde ein wenig Zeit brauchen, um mich von meinen Wunden zu erholen. Ohne meine Sachen bin ich ohnehin keine große Hilfe in einem Kampf. Könntet Ihr meine Ausrüstung für mich suchen?\n\nZuletzt sah ich meine Rüstung in einer Truhe neben diesem großen Turm südlich von hier liegen. Mein Dolch befindet sich im Südwesten und mein Streitkolben drüben nahe dem Lavafeld im Westen.", sourceObjective = "Besorgt Owynns Dolch, Streitkolben und Rüstung.", progress = "Ich muss mich nur wieder eingewöhnen. Von Ogern verprügelt zu werden, verursacht doch einige Schmerzen. Wer hätte das gedacht?", completion = "Danke, sieht so aus, als wäre alles noch gut in Schuss. Gebt mir nur einen Moment, um alles anzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34286] = { id = 34286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Wahrheit", description = "In Ordnung, kommen wir zum Geschäft.\n\nDie Blutschläger haben irgendein monströses Artefakt ausgegraben, das sie Seelenschänder nennen. Es ist so ein fieses Zauberwerk, mit dem sich ihr Häuptling unglaubliche magische Macht verleiht. Er muss es jedoch dafür mit Seelen nähren. Tag für Tag stapeln sich mehr Leichen von Sklaven, die getötet wurden, um das Artefakt zu unterhalten.\n\nWir müssen Borgal finden und diesen Seelenschänder loswerden.", sourceObjective = "Sucht nach Borgal Unheilfaust.", completion = "Abgelegene Höhle jenseits der Lava, passt.\n\nGruseliger Knochenhaufen, passt.\n\nIn Ordnung, das scheint der richtige Ort zu sein. Wir werden aufpassen müssen. Ich wette, Borgal ist hier nicht allein.", sourceObjectiveStatus = "unverified-source-field" }
quests[34287] = { id = 34287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Läutern der Seelen", description = "Nicht alle Geister werden durch den Seelenschänder zerstört. Einige Seelen, wie auch ich, schaffen es, mehr oder weniger unversehrt zu überleben. Andere wurden entstellt und wahnsinnig.\n\nBeendet ihr Elend. Nehmt meinen Seelensplitter und läutert sie. Ihre Raserei wird sie für die Auswirkungen seiner Energie blind machen, daher müsst Ihr sie besiegen, bevor Ihr ihn einsetzen könnt.", sourceObjective = "Läutert 10 wahnsinnige Seelen.", completion = "Danke, ich bin froh, dass die Geister von ihren Qualen erlöst wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[34288] = { id = 34288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bindenden Totems", description = "Bevor Borgal anfing, den Seelenschänder einzusetzen, hat er Geister mithilfe von Totems in seinen Dienst gezwungen.\n\nWenn wir ein paar dieser Totems in die Finger bekommen können, bin ich vielleicht in der Lage, die von ihm geschmiedeten Geistverbindungen zu nutzen, um eine Verbindung herzustellen. Er wäre gezwungen, vor uns zu erscheinen!\n\nBesorgt mir ein paar dieser Totems, dann kann ich das vielleicht durchziehen. Ich glaube, fünf sollten ausreichen.", sourceObjective = "Sammelt 5 von Borgals Totems.", progress = "Habt Ihr die Totems, um die ich Euch gebeten habe? Er hat sie bei den Gebäuden in der Nähe zurückgelassen.", completion = "Sehr gut, ich kann starke Magie in ihnen spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[34289] = { id = 34289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebende des Seelenschänders", description = "Es wird Zeit, dass Borgal stirbt.\n\nWir müssen zu einem Ort der Macht reisen, wo ich Platz für dieses Ritual habe. Im Nordwesten liegt eine Turmruine, die sich perfekt dafür eignet. Trefft Euch dort mit uns und platziert die Totems an den Machtpunkten, die Ihr dort findet. Sobald alle an Ort und Stelle sind, werde ich das Ritual durchführen, das Borgal zu uns beschwören wird.\n\nEuch wird die schwierige Aufgabe zufallen, ihn zu töten!", sourceObjective = "Platziert Borgals Totems, damit Orlana mit dem Ritual beginnen kann, und tötet dann Borgal.", completion = "Was für ein Mordskampf! Verdammt guter Kampf, Mann... ähm Kommandant.\n\nOrlana war wirklich eine große Hilfe. Ich habe mich ein wenig umgehört. Vielleicht fällt einem Priester etwas ein, wie wir ihr helfen können.\n\nWir müssen uns auf jeden Fall noch um dieses Artefakt kümmern. Ihr solltet es behalten, sonst schnappt es sich noch irgendein machthungriger Irrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[34290] = { id = 34290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatz: Ketyas Vorratskiste" }
quests[34291] = { id = 34291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Herz", description = "Habt Ihr die magische Barriere bemerkt, die den Eingang zur Höhle schützt? Sie wird von dämonischen Kristallen mit Energie versorgt.\n\nDie Brennende Legion hat die Angewohnheit, Teile von Dämonen zu Schlüsseln für solche Gerätschaften zu machen.\n\nReist nach Westen zu den Ruinen von Ata'gar. Sucht in ihnen nach einem mächtigen Dämon und bringt mir sein Herz.\n\nIch werde ein Abbild meiner selbst in die Ruinen projizieren. Ihr werdet nicht hierher zurückkehren müssen, bis wir alles erledigt haben.", sourceObjective = "Besorgt das Herz von Fernus.", progress = "Habt Ihr den Dämonenschlüssel?", completion = "Ein Herz? Wie rührend.\n\nSchnell. Wir müssen damit die Teufelskristalle zerstören und dann zu Gul'dan eilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34292] = { id = 34292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminiert den Schattenrat", description = "Diese Ruinen werden bald voller Handlanger des Schattenrats sein. Wir können uns nicht leisten, dass sie sich in ganz Draenor ausbreiten, wenn Ihr Euch erst um Gul'dan gekümmert habt.\n\nNein, wir müssen jeden Einzelnen von ihnen auslöschen... bis zum letzten Orc.", sourceObjective = "Tötet 12 Mitglieder des Schattenrats bei den Ruinen von Ata'gar.", completion = "Es ist notwendig. Wir können es nicht riskieren, dass der Rat noch mächtiger wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[34293] = { id = 34293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminiert den Schattenrat", description = "Diese Ruinen sind voller Anhänger des Schattenrats. Wir können uns nicht leisten, dass sie sich in ganz Draenor ausbreiten, wenn Gul'dan erst einmal besiegt ist.\n\nNein, wir müssen jeden Einzelnen von ihnen auslöschen... bis zum letzten Orc.", sourceObjective = "Tötet 12 Mitglieder des Schattenrats bei den Ruinen von Ata'gar.", completion = "Es ist notwendig. Wir können es nicht riskieren, dass der Rat noch mächtiger wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[34294] = { id = 34294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teufelskristalle", description = "Ihr habt den Schlüssel. Setzt ihn jetzt ein, um die Teufelskristalle zu zerstören.\n\nWenn sie erst vernichtet sind, wird die magische Barriere, die den Eingang zur Finsterspitze blockiert, zusammenbrechen.\n\nSobald die Barriere entfernt ist, geht Ihr hinein und fordert Gul'dan heraus.", sourceObjective = "Zerstört die Teufelskristalle.", completion = "Die Barriere ist weg. Jetzt ist es Zeit, Gul'dan gefangen zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34295] = { id = 34295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gul'dan gefangen nehmen", description = "Gul'dan befindet sich tief in der Höhle der Finsterspitze.\n\nWir wissen, dass er im Begriff ist, nach Talador und zum Schattenmondtal aufzubrechen. Ihr müsst ihn unter allen Umständen gefangen nehmen, {name}.\n\nWir sehen uns in Throm'var. Viel Glück.", sourceObjective = "Stellt Gul'dan.", completion = "Bedauerlich, aber nicht überraschend. Wenigstens konnten wir eins der Mitglieder des inneren Rats besiegen.\n\nEs ist nicht alles verloren, {name}. Wir wissen, was der Schattenrat vorhat und was sein Ziel ist.\n\nWir werden uns in Talador neu sammeln. Zusammen werden wir Teron'gor und seinen Plänen für Auchindoun ein Ende setzen.\n\nHabt Ihr das gehört...?", sourceObjectiveStatus = "unverified-source-field" }
quests[34309] = { id = 34309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Die Suche nach Schattenjägerin Bwu'ja", description = "Es ist schon lange her, seit wir was von Schattenjägerin Bwu'ja gehört hab'n, Kommandant.\n\nDas Letzte, was wir von ihr wiss'n, ist, dass sie den Auftrag hatte, diese Blutschlägeroger oben am Frostfeuergrat im Auge zu behalt'n.\n\nDiese Oger sind bloß ein Haufen Sklaventreiber, also muss etwas echt Großes passiert sein, dass sie sich nicht meld'n kann.\n\nGeht rüber zu den Steinzornklippen und sucht nach ihr.", sourceObjective = "Rettet Sklaven in den Steinzornklippen, um Hinweise zum Aufenthaltsort von Schattenjägerin Bwu'ja zu erhalten.", completion = "He, hallo, Mann! Schön, hier'n freundliches Gesicht zu seh'n, aber ich hab nich' erwartet, dass sich meinetwegen der Kommandant persönlich hierher bemüht!", sourceObjectiveStatus = "unverified-source-field" }
quests[34311] = { id = 34311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Invasion: Opted Out" }
quests[34312] = { id = 34312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Magmafürst" }
quests[34313] = { id = 34313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orlana Starkstirn" }
quests[34314] = { id = 34314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Ketten befreit", description = "Hört mal, Mann, diese Oger hab'n mich mit so 'nem Artefakt mit mächtigem Mojo angefall'n. Das Nächste, was ich weiß, is', dass ich hier mit gebrochenen Knochen und dieser Kette am Bein aufgewacht bin. Ich hab die Geister angeruf'n, sie zu spreng'n, aber von den Geistern hier kam keine Antwort.\n\nDa müss'n wir wohl mit den alten Methoden versuch'n rauszukommen. Da is' so ein großer Oger in der Höhle, der Rugrum heißt. Der hat den Schlüssel zu meinen Fesseln. Könnt Ihr ihm 'ne Klinge in den Bauch rammen und mir diesen Schlüssel besorg'n?", sourceObjective = "Besorgt den Sklavenschlüssel der Blutschläger und befreit Schattenjägerin Bwu'ja.", progress = "Macht Euch um mich keine Sorgen, Mann. Ich geh nirgendwo hin.", completion = "Ah, jetzt, ja. Das fühlt sich gleich viel besser an!", sourceObjectiveStatus = "unverified-source-field" }
quests[34315] = { id = 34315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufrüstung", description = "Diese Oger haben mich echt gründlich verdroschen. Mein Arm is' gebrochen, ein paar Rippen angeknackst, ich glaub, mir tut sogar meine Milz von der Prügel weh. Nichts, womit ein Troll nich' klarkommt, aber ich brauch doch 'nen Moment, um mich etwas zu erhol'n.\n\nUnd ich brauch echt meine Ausrüstung, die mir die Oger abgenommen haben. Mein Gewand hab'n sie in 'ne Truhe in 'ner Hütte im Süden gelegt, meine Gleve in 'ne Truhe neben dem Turm mit den Knochenbrechern, und sogar meine Maske hab'n sie genommen! Sie liegt nahe der Lava. Könnt Ihr mir mein Zeug hol'n, während ich etwas zu Atem komme?", sourceObjective = "Besorgt Bwu'jas Gewand, Gleve und Maske.", progress = "Ah, habt Ihr das gehört? Glaub, da is noch 'ne Rippe zurück an ihren Platz gesprung'n.", completion = "Ah, da is' mein Zeug ja! Gebt mir 'nen Moment, dann leg ich alles an, Mann. Dann werd ich mir ein Ogerohr für jeden Knochen nehmen, den ich mir wieder einrenk'n musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[34316] = { id = 34316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Wahrheit", description = "Hört mal, Mann, vor ein paar Nächten hab'n diese Oger so'n altes, mächtiges Mojo gefund'n.\n\nIch hab mich ein wenig bei der Höhle hinter'm Lavafluss umgeseh'n, da hab ich einen lauten Schrei aus der Geisterwelt gehört. Da bin ich reingegang'n und hab Borgal, den Ogerhäuptling, geseh'n, wie er die Geister aus den Sklaven herausgezog'n hat. Er hat dazu so'n großes Steinrad benutzt, das sie Seelenschänder genannt hab'n. Ich hab versucht, sie fertigzumach'n, aber ein einziger Schuss aus diesem Ding hat mir echt die ganze Stärke genommen.\n\nDieses Mojo is' in den Händen von diesen Ogern echt zu gefährlich.", sourceObjective = "Sucht nach Borgal Unheilfaust.", completion = "Das is der Ort. Wir müssen vorsichtig sein, Borgal un' das Artefakt sind da drin.", sourceObjectiveStatus = "unverified-source-field" }
quests[34318] = { id = 34318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bindenden Totems", description = "Bevor Borgal anfing, den Seelenschänder einzusetzen, hat er Geister mithilfe von Totems in seinen Dienst gezwungen.\n\nWenn wir ein paar dieser Totems in die Finger bekommen können, bin ich vielleicht in der Lage, die von ihm geschmiedeten Geistverbindungen zu nutzen, um eine Verbindung herzustellen. Er wäre gezwungen, vor uns zu erscheinen!\n\nBesorgt mir ein paar dieser Totems, dann kann ich das vielleicht durchziehen. Ich glaube, fünf sollten ausreichen.", sourceObjective = "Sammelt 5 von Borgals Totems.", progress = "Habt Ihr die Totems, um die ich Euch gebeten habe? Er hat sie bei den Gebäuden in der Nähe zurückgelassen.", completion = "Sehr gut, ich kann starke Magie in ihnen spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[34319] = { id = 34319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebende des Seelenschänders", description = "Es wird Zeit, dass Borgal stirbt.\n\nWir müssen zu einem Ort der Macht reisen, wo ich Platz für dieses Ritual habe. Im Nordwesten liegt eine Turmruine, die sich perfekt dafür eignet. Trefft Euch dort mit uns und platziert die Totems an den Machtpunkten, die Ihr dort findet. Sobald alle an Ort und Stelle sind, werde ich das Ritual durchführen, das Borgal zu uns beschwören wird.\n\nEuch wird die schwierige Aufgabe zufallen, ihn zu töten!", sourceObjective = "Platziert Borgals Totems, damit Orlana mit dem Ritual beginnen kann, und tötet dann Borgal.", completion = "Das war der Kampf des Jahrhunderts, Mann! Bwu'ja is' froh, dass Ihr hier seid, Kommandant, sonst wär ich für immer in der Geisterwelt.\n\nDieser Seelenschänder ist echt fieses Mojo. Am besten behaltet Ihr es.\n\nDieser Geist hat uns echt viel geholf'n, Mann. Ich hoffe, sie findet jetzt den Frieden, den sie gesucht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[34321] = { id = 34321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche der Vergangenheit", description = "Diese Oger sind eine Plage für mein Volk. Sie beschwören und versklaven uns. Wir müssen ohne Rast arbeiten, bis unsere Hitze vergeht und wir zu Staub zerfallen.\n\nUnsere Asche muss zum Lavafluss zurückkehren, damit wir wiedergeboren werden können!\n\nDie Oger tragen die Asche in Beuteln mit sich herum, weil sie glauben, sie würde ihnen Stärke verleihen. Erschlagt sie und holt die Asche meines Volkes zurück!", sourceObjective = "Molthron im Gebiet der Blutschläger möchte, dass Ihr ihm 6 Haufen Elementarasche bringt.", progress = "Bringt Ihr mir die Überreste unserer Gefallenen?", completion = "Danke, Fleischkreatur. In der Lava wird sich die Asche vermischen, und der Zyklus wird fortgesetzt wie seit Anbeginn.", sourceObjectiveStatus = "unverified-source-field" }
quests[34325] = { id = 34325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammen der Erde", description = "Ich habe die Tiefen der Erde durchsucht und das Mittel gefunden, mit dem ich die Zauber, die meine Leute gefangen halten, brechen kann. Es befreit jedoch nur jemanden, der vollständig gebunden ist. Ich könnte damit nicht verhindern, dass ich selbst durch diese Magie gebunden werde.\n\nIhr stammt als Fleischkreatur nicht von den Flammen der Tiefe ab, daher sollten ihre Bindungszauber auf Euch keine Wirkung haben.\n\nNehmt bitte mein Juwel und setzt seine Macht ein, um meine Leute zu befreien!", sourceObjective = "Molthron im Gebiet der Blutschläger möchte, dass Ihr das flammengeschliffene Juwel einsetzt, um 6 Magmaelementare zu befreien.", completion = "Die Lava brennt bereits hell ob der wiedergewonnen Freiheit meines Volks!\n\nWir werden Rache an den Ogern üben für alles, was sie uns angetan haben, das versichere ich Euch. Für den Moment aber werden wir erst einmal ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34326] = { id = 34326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wenden", description = "Es wird Zeit, dass wir uns an diesem Feind rächen. Trefft mich am Platz der Vergelter. Dann werden wir in den Kampf gegen den Schattenrat ziehen.\n\nTeron'gor wird keine einzige Seele mehr fressen, solange wir ihm im Weg stehen! Seine Schreckensherrschaft endet heute.", sourceObjective = "Sprecht mit Restalaan am Platz der Vergelter.", completion = "Dank Eurer Hilfe konnten die Feinde zurückgeschlagen und die Verteidigungen von Auchindoun erneuert werden, aber wir sind hier noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[34328] = { id = 34328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählt: 'Segen des Wolfs'" }
quests[34329] = { id = 34329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählt: 'Stürmische Zornböen'" }
quests[34330] = { id = 34330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählt: 'Ogerkraft'" }
quests[34331] = { id = 34331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählt: 'Geist des Wolfs'" }
quests[34332] = { id = 34332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählt: 'Feuerberührung'" }
quests[34333] = { id = 34333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgewählt: 'Eisberührung'" }
quests[34335] = { id = 34335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnisonskampagne: Krähen unterwegs", description = "Unsere Druiden haben ein weit gefächertes Spähernetzwerk in Gorgrond etabliert, um die Ergebnisse Eurer Berichte aus Nagrand weiter zu verfolgen.\n\nWir haben verdächtige Ausgrabungsarbeiten der Eisernen Horde in der Nähe einiger Salzseen an der Westküste Gorgronds ausfindig gemacht.\n\nWir haben Grund zu der Annahme, dass diese Orcs tief in der Wüste hinter einem wertvollen Artefakt her sind.\n\nIch werde eine kleine Truppe für einen konzentrierten, gezielten Angriff zusammenstellen. Uns fehlt aber noch <ein fähiger/eine fähige:c> {class}, und da hatte ich an Euch gedacht.", sourceObjective = "Sprecht mit Thisalee Krähe an der Horizontklippe in Gorgrond.", completion = "Seid gegrüßt, {class}. Seid Ihr der Kommandant, von dem Choluna gesprochen hat?\n\n\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[34336] = { id = 34336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfall auf den Feind", description = "Seht Ihr das Lager der Eisernen Horde im Süden jenseits des Wassers? Wir beobachten ihre Bewegungen schon seit Tagen.\n\nWir haben festgestellt, dass reger Austausch zwischen ihrem Hauptmann und dem Kommandanten der Eisernen Horde in Nagrand herrscht.\n\nWir müssen ihre Operation stören.\n\nSammelt ihre Vorräte ein und bringt mir den Kopf ihres Anführers.", sourceObjective = "Besorgt 5 Karawanenlieferungen und Leutnant O'roks Kopf.", progress = "Diese Orcs verrichten nur die Schmutzarbeit anderer.", completion = "Ich wusste, Ihr seid die richtige Person für diese Aufgabe, {name}. Das Ergebnis kann sich wirklich sehen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[34337] = { id = 34337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der riesige Kessel", description = "Ein hochwertiges Artefakt am Rauchfelskessel, hmm?\n\nSchau'n wird doch mal, ob wir der Eisernen Horde nicht zuvorkommen können.\n\nWir müssen uns beeilen. Sprecht mit Choluna und wir machen uns auf den Weg.", sourceObjective = "Sprecht mit Choluna.", completion = "Das ist es also, hm? Sehen wir einmal nach, was sich in diesen Tiefen verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
